add(1931,9,18,'JAPAN','戰','만주사변','관동군이 류탸오후의 철도를 스스로 폭파하고 만주를 점령했다.',[H('만주 점령','만주 장악',E=>E.conquerNear('JAPAN',[125.5,44],600,{from:'ROC',boost:1.5}))],{maj:1,cond:E=>E.has('JAPAN')&&E.has('ROC')&&E.y<1945});
