add(1940,6,22,'GERMANY','戰','프랑스의 항복','전격전 6주 만에 파리가 함락되었다.',[H('점령','프랑스 북부 점령',E=>{E.conquer('GERMANY','FRANCE',{box:[-5,46,8.5,51.5],boost:2});E.peace('GERMANY','FRANCE');})],{cond:E=>E.hf('GERMANY','ww2')&&E.atWar('GERMANY','FRANCE')});
