add(1945,9,2,null,'災','제2차 세계대전의 희생','6년의 전쟁으로 7000만 명 이상이 죽었다. 소련·폴란드·중국·독일의 피해가 가장 컸다.',[H('','유럽 −6%, 동아시아 −3%',E=>{E.plague([-10,36,60,65],.06);E.plague([100,18,145,50],.03);})],{maj:1,cond:E=>E.hf('JAPAN','ww2')||E.hf('GERMANY','ww2')||E.has('WGER')});
