add(1952,4,28,'JAPAN','外','샌프란시스코 강화 조약','연합국의 점령이 끝나고 일본이 주권을 되찾았다.',[H('주권 회복','일본으로 개칭',E=>{E.rename('JAPAN','일본');E.mod('JAPAN',{army:2});})],{cond:E=>E.has('JAPAN')});
