add(1994,7,8,'DPRK','政','김일성 사망과 고난의 행군','김일성이 죽고 홍수와 가뭄이 겹쳤다. 배급제가 무너지고 수십만 명이 굶어 죽었다.',[H('고난의 행군','인구 -3%, 안정도 -1, 「선군정치」',E=>{E.mod('DPRK',{pop:-.03,stab:-1});E.pol('DPRK','songun');}),O('개방을 택한다','「개방 외교」, 안정도 -1.5 (역사 개변 +12)',E=>{E.pol('DPRK','openness');E.unpol('DPRK','juche');E.mod('DPRK',{stab:-1.5});},false,12)],{maj:1,cond:E=>E.has('DPRK')});
add(1997,11,21,'ROK','商','IMF 외환위기','외환보유고가 바닥났다. 정부가 IMF에 구제금융을 신청했다. 국민들은 금 모으기 운동으로 227톤의 금을 모은다.',
 [H('구제금융을 받는다 (역사)','국고 +1년치, 생산 -15% (3년), 「신자유주의 개혁」',E=>{E.mod('ROK',{gold:1,stab:-1});E.tmod('ROK','prod',-.15,3,'IMF');E.pol('ROK','neolib');}),
  O('모라토리엄을 선언한다','안정도 -2, 생산 -25% (5년) (역사 개변 +8)',E=>{E.mod('ROK',{stab:-2});E.tmod('ROK','prod',-.25,5,'모라토리엄');},false,8)],{maj:1,cond:E=>E.has('ROK')});
add(2000,6,13,'ROK','外','남북 정상회담','김대중 대통령과 김정일 국방위원장이 평양에서 만났다. 6·15 남북 공동선언.',[H('만난다','안정도 +1 (남북)',E=>{E.mod('ROK',{stab:1});E.mod('DPRK',{stab:.5});}),O('대화를 미룬다','변화 없음',E=>{},false,4)],{cond:E=>E.has('ROK')&&E.has('DPRK')});
add(2006,10,9,'DPRK','兵','북한 핵실험','함경북도 풍계리에서 첫 지하 핵실험이 있었다.',[H('실험','핵무기 습득, 안정도 +0.5',E=>{E.tech('DPRK','nucphys',1);E.tech('DPRK','nuke',1);E.mod('DPRK',{stab:.5});}),O('포기하고 제재를 푼다','국고 +1년치 (역사 개변 +10)',E=>E.mod('DPRK',{gold:1}),false,10)],{maj:1,cond:E=>E.has('DPRK')});
